#version 300 es
precision highp float; precision highp int;
uniform sampler2D uS; uniform vec2 uRes; uniform float uT,uPx,uStruct,uMirror,uFloorY;
uniform vec4 uLayer; uniform ivec4 uLayerEnd;
uniform float uP[30];
out vec3 vPos; out vec3 vT; out float vSide; out float vEm; out float vAlb; out float vFade;
const int ROWS=10000;
float h1(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }

uniform mat4 uV; uniform float uF,uAspect,uFish;
// returns ndc.xy, distance; ok=0 when the point cannot be shown
vec3 proj(vec3 p,out float ok){
  vec3 v=(uV*vec4(p,1.)).xyz; float d=length(v), z=-v.z;
  vec2 pp=v.xy*uF/max(z,.05);
  float th=acos(clamp(z/max(d,1e-5),-1.,1.)), rl=length(v.xy);
  vec2 fp=rl>1e-5?v.xy/rl*th/1.2217:vec2(0.);
  ok=(uFish<.999?step(.15,z):1.)*step(th,2.7)*step(.05,d);
  vec2 n=mix(pp,fp,uFish); n.x/=uAspect;
  return vec3(n,d);
}
void main(){
  const int S=128;
  int k=gl_InstanceID%(S-1), i=gl_InstanceID/(S-1);
  bool st=uStruct>.5;
  ivec2 t=st?ivec2(k,i):ivec2((i/ROWS)*S+k,i%ROWS);
  vec4 a=texelFetch(uS,t,0), b=texelFetch(uS,t+ivec2(1,0),0);
  float side=(gl_VertexID&1)==0?-1.:1., end=gl_VertexID<2?0.:1.;
  vec3 pa=a.xyz, pb=b.xyz;
  if(uMirror>0.){ pa.y=2.*uFloorY-pa.y; pb.y=2.*uFloorY-pb.y; }
  float oka,okb; vec3 na=proj(pa,oka), nb=proj(pb,okb);
  bool ok=a.w>=0.&&b.w>=0.&&a.w>=b.w&&oka*okb>.5;
  float id=float(i), u=(float(k)+end)/float(S), amt=1.; int layer=-1;
  if(st){ layer=i<uLayerEnd.x?0:i<uLayerEnd.y?1:i<uLayerEnd.z?2:3; amt=uLayer[layer]; ok=ok&&amt>.002&&!(uMirror>0.&&layer==0); }
  if(!ok){ gl_Position=vec4(2.,2.,2.,1.); vPos=vec3(0.); vT=vec3(1.,0.,0.); vSide=0.; vEm=0.; vAlb=0.; vFade=0.; return; }
  vec2 d=(nb.xy-na.xy)*uRes; float L=length(d);
  vec2 n=L>1e-4?vec2(-d.y,d.x)/L:vec2(0.,1.);
  vec3 cp=mix(na,nb,end);
  float fade,em,alb,wm=1.;
  if(st){
    float h=h1(vec2(id,71.));
    fade=smoothstep(0.,.06,amt*1.4-u-.3*h);                       // lines grow in from their start as the layer comes up
    em=uP[14]*.8*pow(.5+.5*sin(u*7.-uT*1.3+h*6.2832),30.);
    alb=(layer==0?1.1:mix(.25,1.1,h))*min(amt,1.5); wm=layer==0?.7:mix(.7,1.3,h1(vec2(id,13.)));
    if(layer==0) fade*=exp(-mix(.07,.45,uFish)*cp.z);
  }else{
    float age=mix(a.w,b.w,end);
    fade=smoothstep(uP[13],uP[13]*.55,u)*smoothstep(0.,.25,age+u);
    em=uP[14]*1.1*pow(.5+.5*sin(age*2.2-uT*1.8+h1(vec2(id,5.))*1.5),14.);
    alb=mix(.05,1.,pow(h1(vec2(id,2.)),1.5));
  }
  float wpx=uP[15]*uPx*wm*clamp(3.6/cp.z,.5,2.5)*mix(.35,1.,fade);
  gl_Position=vec4(cp.xy+n*side*wpx/uRes,clamp(cp.z/60.,0.,1.)*2.-1.,1.);
  vec3 wp=mix(a.xyz,b.xyz,end);
  float fog=exp(-.2*max(cp.z-2.6,0.));
  float mir=uMirror>0.?uMirror*exp(-max(wp.y-uFloorY,0.)*.7):1.;
  vec3 tangent=b.xyz-a.xyz;
  vec4 prev=texelFetch(uS,t-ivec2(k>0?1:0,0),0);
  vec4 next=texelFetch(uS,t+ivec2(k<S-2?2:1,0),0);
  vec3 ta=k>0&&prev.w>=a.w?b.xyz-prev.xyz:tangent;
  vec3 tb=k<S-2&&next.w>=0.&&b.w>=next.w?next.xyz-a.xyz:tangent;
  vPos=wp; vT=mix(ta/max(length(ta),.000001),tb/max(length(tb),.000001),end); vSide=side; vEm=em; vAlb=alb; vFade=fade*fog*mir;
}

VS_DOT:
#version 300 es
precision highp float;
uniform vec4 uL[3]; uniform float uPx,uMirror,uFloorY;
out float vI;

uniform mat4 uV; uniform float uF,uAspect,uFish;
// returns ndc.xy, distance; ok=0 when the point cannot be shown
vec3 proj(vec3 p,out float ok){
  vec3 v=(uV*vec4(p,1.)).xyz; float d=length(v), z=-v.z;
  vec2 pp=v.xy*uF/max(z,.05);
  float th=acos(clamp(z/max(d,1e-5),-1.,1.)), rl=length(v.xy);
  vec2 fp=rl>1e-5?v.xy/rl*th/1.2217:vec2(0.);
  ok=(uFish<.999?step(.15,z):1.)*step(th,2.7)*step(.05,d);
  vec2 n=mix(pp,fp,uFish); n.x/=uAspect;
  return vec3(n,d);
}
void main(){
  vec4 l=uL[gl_VertexID]; vec3 p=l.xyz; if(uMirror>0.) p.y=2.*uFloorY-p.y;
  float ok; vec3 n=proj(p,ok);
  gl_Position=ok>.5?vec4(n.xy,clamp(n.z/60.,0.,1.)*2.-1.,1.):vec4(2.,2.,2.,1.);
  gl_PointSize=clamp(uPx*70./max(n.z,.25),4.,260.);
  vI=min(l.w,3.)*(uMirror>0.?uMirror*.5:1.);
}

FS_SIM:
#version 300 es
precision highp float;
uniform sampler2D uS;
uniform float uT,uDt,uShift,uSeed,uMode,uActive;
uniform float uP[30];
out vec4 o;
const int SEGC=128, ROWS=10000;
const float FLOOR=-1.55+.015;
float h1(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
vec3 h3(vec2 p){ return vec3(h1(p),h1(p+17.1),h1(p+41.7)); }
const mat3 R=mat3(0.,.8,.6,-.8,.36,-.48,-.6,-.48,.64);
const vec3 AX=vec3(.3304,.9441,.1888);
vec3 pot(vec3 p){
  vec3 s=vec3(0.); float a=1.; p*=uP[1];
  for(int i=0;i<3;i++){ p=R*p*1.7+vec3(0.,uT*uP[2],3.1); s+=a*sin(p.yzx+1.3*cos(p.zxy)); a*=.55; }
  return s;
}
vec3 curl(vec3 p){
  const float e=.02;
  vec3 dx=pot(p+vec3(e,0,0))-pot(p-vec3(e,0,0));
  vec3 dy=pot(p+vec3(0,e,0))-pot(p-vec3(0,e,0));
  vec3 dz=pot(p+vec3(0,0,e))-pot(p-vec3(0,0,e));
  return vec3(dy.z-dz.y, dz.x-dx.z, dx.y-dy.x)/(2.*e*uP[1]*4.);
}
vec3 emitter(){ return vec3(1.5*sin(.37*uT),.8*sin(.53*uT+1.),.9*sin(.29*uT+2.)); }
vec3 vel(vec3 p,float id){
  vec3 v=curl(p)*uP[0];
  float h=dot(p,AX); vec3 rp=p-AX*h; float r=length(rp);
  v+=uP[3]*cross(AX,rp)/(.25+1.2*r*r);
  v+=uP[5]*rp/(r+.15);
  v+=uP[4]*p/(length(p)+.1);
  v.y+=uP[6]*(uP[6]>0.?smoothstep(1.7,-.6,p.y):smoothstep(-1.7,.6,p.y));
  v-=uP[7]*p*smoothstep(1.2,2.4,length(p));
  v+=uP[25]*(emitter()+(h3(vec2(id,23.))-.5)*vec3(.9,.5,.5)-p);
  return v;
}
vec3 spawn(vec3 r){
  if(uMode<.5){
    vec3 u=normalize(cross(AX,vec3(1,0,0))), w=cross(AX,u);
    float a=r.x*6.2832, rr=.04+.22*sqrt(r.y);
    return AX*(r.z-.5)*1.5+(u*cos(a)+w*sin(a))*rr;
  }else if(uMode<1.5){
    float k=floor(r.x*9.)+floor(uT/30.)*13.;
    vec2 c=(vec2(h1(vec2(k,3.)),h1(vec2(k,9.)))-.5);
    return vec3(c.x*3.4,-1.45,c.y*1.5)+vec3(r.y-.5,0.,r.z-.5)*.16;
  }else if(uMode<2.5){
    float z=r.x*2.-1., a=r.y*6.2832, s=sqrt(1.-z*z);
    return vec3(s*cos(a),z,s*sin(a))*(.12+.1*r.z);
  }else if(uMode<3.5){
    return (r-.5)*vec3(4.4,2.8,3.2);
  }else if(uMode<4.5){
    float x=(r.x-.5)*4.8;
    return vec3(x,1.75+.05*r.z,.55*sin(x*1.3+uT*.12)+(r.y-.5)*.06);
  }else if(uMode<5.5){
    return emitter()+(r-.5)*.6;
  }else if(uMode<6.5){
    vec3 u=normalize(cross(AX,vec3(1,0,0))), w=cross(AX,u);
    float a=r.x*6.2832, rr=1.7+.5*r.y;
    return AX*(r.z-.5)*.7+(u*cos(a)+w*sin(a))*rr;
  }
  float k=floor(r.x*9.), a=(k+.5*h1(vec2(k,3.)+floor(uT/30.)))/9.*6.2832, rr=1.0+.6*h1(vec2(k,9.));
  return vec3(cos(a)*rr,-1.45,sin(a)*rr)+vec3(r.y-.5,0.,r.z-.5)*.16;
}
void main(){
  ivec2 c=ivec2(gl_FragCoord.xy); int kx=c.x%SEGC; float id=float((c.x/SEGC)*ROWS+c.y);
  if(id>=uActive){ o=vec4(0.,0.,0.,-1.); return; }
  float sp=uP[17]*(.6+.8*h1(vec2(id,7.)));
  if(kx==0){
    vec4 s=texelFetch(uS,c,0);
    if(s.w<0.){
      float env=mix(1., pow(.5+.5*cos(6.2832*uT*uP[18]),8.)*6., uP[11]);
      if(h1(vec2(id,uSeed))<uP[10]*uDt*env) s=vec4(spawn(h3(vec2(id,uSeed+3.7))),0.);
    }else{
      s.xyz+=vel(s.xyz,id)*sp*uDt; s.y=max(s.y,FLOOR); s.w+=uDt;
      if(s.w>uP[8]+uP[9]*h1(vec2(id,11.))) s.w=-1.;
    }
    o=s;
  }else{
    vec4 s=uShift>.5?texelFetch(uS,c-ivec2(1,0),0):texelFetch(uS,c,0);
    if(s.w>=0.){ s.xyz+=(vel(s.xyz,id)-uP[25]*(emitter()-s.xyz))*sp*uDt*uP[12]; s.y=max(s.y,FLOOR); }
    o=s;
  }
}

FS_LINE:
#version 300 es
precision highp float;
in vec3 vPos; in vec3 vT; in float vSide; in float vEm; in float vAlb; in float vFade;
uniform vec3 uCam; uniform vec4 uL[3]; uniform float uAmb,uMetal,uRange;
uniform float uRoughness,uAnisotropy,uSpecular,uEnv,uEnvAngle,uEnvWidth,uWarmth,uEmission,uLegacy;
out vec4 o;
float legacy(vec3 T,vec3 V,vec3 N){
  float sh=mix(10.,80.,clamp(uMetal*.5,0.,1.)), c=0.;
  for(int l=0;l<4;l++){
    vec3 Ld; float att;
    if(l<3){ vec3 Lv=uL[l].xyz-vPos; float d2=dot(Lv,Lv); Ld=Lv*inversesqrt(d2+1e-6); att=uL[l].w/(1.+d2*uRange); }
    else{ Ld=normalize(vec3(.35,.8,.45)); att=.45*uAmb; }      // fixed overhead key so the room stays readable away from the moving lights
    vec3 Hh=normalize(Ld+V); float nl=max(dot(N,Ld),0.);
    float th=dot(T,Hh), kk=pow(max(1.-th*th,0.),sh*.5), sp=pow(max(dot(N,Hh),0.),sh);
    c+=att*(.18*nl+uMetal*(.6*kk*(.2+.8*nl)+1.4*sp));
  }
  vec3 R=reflect(-V,N);
  float env=smoothstep(.35,.95,R.y)*.5+pow(1.-abs(R.y),8.)*.25;
  float rim=pow(1.-max(dot(N,V),0.),3.);
  c+=uAmb*(.04+uMetal*.1*env+.06*rim);
  c=c*vAlb+vEm;
  return c;
}
float softbox(vec3 r,vec3 forward,vec3 up,vec2 size,float blur){
  vec3 side=normalize(cross(forward,up)); up=cross(side,forward);
  float facing=dot(r,forward);
  vec2 p=vec2(dot(r,side),dot(r,up))/max(facing,.03);
  vec2 aa=max(fwidth(p)*.6,vec2(.002));
  vec2 mask=1.-smoothstep(size-aa,size+vec2(blur)+aa,abs(p));
  return mask.x*mask.y*smoothstep(0.,.15,facing);
}
vec3 studio(vec3 r,float rough){
  float a=radians(uEnvAngle), c=cos(a), s=sin(a);
  r=vec3(c*r.x-s*r.z,r.y,s*r.x+c*r.z);
  float blur=rough*rough*.7;
  float key=softbox(r,normalize(vec3(.7,.35,.7)),vec3(0,1,0),vec2(uEnvWidth,.95),blur);
  float fill=softbox(r,normalize(vec3(-.65,.25,.7)),vec3(0,1,0),vec2(uEnvWidth*.65,.7),blur);
  float top=softbox(r,normalize(vec3(0,1,-.25)),vec3(0,0,1),vec2(.85,uEnvWidth),blur);
  return vec3(.014+.035*smoothstep(-.2,.8,r.y))+key*vec3(2.4,2.48,2.6)+fill*vec3(1.45,1.38,1.28)+top*1.6;
}
vec3 fresnel(float cosTheta,vec3 f0){ return f0+(1.-f0)*pow(1.-clamp(cosTheta,0.,1.),5.); }
void main(){
  if(vFade<.004 || dot(vT,vT)<1e-12) discard;
  vec3 T=normalize(vT), V=normalize(uCam-vPos);
  vec3 B=cross(T,V);
  if(dot(B,B)<1e-8) B=cross(T,abs(T.y)<.9?vec3(0,1,0):vec3(1,0,0));
  B=normalize(B);
  vec3 Nf=normalize(cross(B,T));
  float side=clamp(vSide,-.999,.999);
  vec3 N=normalize(B*side+Nf*sqrt(1.-side*side));
  if(uLegacy>.999){ o=vec4(vec3(legacy(T,V,N)*vFade),1.); return; }
  B=normalize(cross(N,T));
  float metal=clamp(uMetal,0.,1.), rough=clamp(uRoughness,.08,1.);
  // Specular anti-aliasing for thin subpixel wires. No extra geometry/pass.
  float variance=min(.06,.12*(dot(dFdx(N),dFdx(N))+dot(dFdy(N),dFdy(N))));
  float alpha=max(.012,rough*rough+variance);
  float at=max(.012,alpha*(1.+uAnisotropy)), ab=max(.012,alpha*(1.-uAnisotropy));
  vec3 tint=mix(vec3(.65,.76,.9),vec3(.94,.76,.53),uWarmth*.5+.5);
  vec3 base=tint*mix(.48,.95,clamp(vAlb,0.,1.));
  vec3 f0=mix(vec3(.04),base,metal), color=vec3(0.);
  float nv=max(dot(N,V),.001), tv=dot(T,V), bv=dot(B,V);
  for(int l=0;l<4;l++){
    vec3 L; float att;
    if(l<3){ vec3 v=uL[l].xyz-vPos; float d2=dot(v,v); L=v*inversesqrt(d2+1e-6); att=uL[l].w/(1.+d2*uRange); }
    else{ L=normalize(vec3(.35,.8,.45)); att=.45*uAmb; }
    vec3 H=normalize(L+V); float nl=max(dot(N,L),0.), nh=max(dot(N,H),0.);
    vec3 h=vec3(dot(T,H)/at,dot(B,H)/ab,nh);
    float d=1./max(3.14159265*at*ab*pow(dot(h,h),2.),.000001);
    float lv=nl*length(vec3(at*tv,ab*bv,nv));
    float ll=nv*length(vec3(at*dot(T,L),ab*dot(B,L),nl));
    float vis=.5/max(lv+ll,.0001);
    vec3 F=fresnel(dot(V,H),f0);
    color+=att*nl*((1.-metal)*(1.-F)*base/3.14159265+min(F*d*vis,vec3(12.))*uSpecular);
  }
  vec3 reflected=reflect(-V,N);
  color+=studio(reflected,rough)*fresnel(nv,f0)*uEnv*uSpecular*mix(1.,.55,rough);
  color+=base*(1.-metal)*uAmb*.045;
  color+=vec3(vEm*uEmission);
  if(uLegacy>.001) color=mix(color,vec3(legacy(T,V,N)),uLegacy);
  o=vec4(color*vFade,1.);
}

