#version 300 es
precision highp float; in float vI; out vec4 o;
void main(){ float r=length(gl_PointCoord-.5)*2.; float g=(exp(-r*r*60.)*5.+exp(-r*r*6.)*.35)*smoothstep(1.,.6,r); o=vec4(vec3(g*vI),1.); }

FS_FLOOR:
#version 300 es
precision highp float;
uniform mat4 uV; uniform float uF,uAspect,uFish,uFloorY,uRange,uAmt; uniform vec2 uInv; uniform vec3 uCam; uniform vec4 uL[3];
out vec4 o;
void main(){
  vec2 n=(gl_FragCoord.xy*uInv*2.-1.)*vec2(uAspect,1.);
  float rl=length(n), th=rl*1.2217;
  vec3 vp=normalize(vec3(n/uF,-1.)), vf=vec3(rl>1e-5?n/rl*sin(th):vec2(0.),-cos(th));
  if(uFish>.5&&th>2.7) discard;
  vec3 dir=normalize(transpose(mat3(uV))*mix(vp,vf,uFish));
  if(dir.y>-1e-4) discard;
  float t=(uFloorY-uCam.y)/dir.y; vec3 p=uCam+dir*t, V=-dir; float c=0.;
  for(int l=0;l<3;l++){
    vec3 Lv=uL[l].xyz-p; float d2=dot(Lv,Lv); vec3 Ld=Lv*inversesqrt(d2+1e-6);
    float att=uL[l].w/(1.+d2*uRange); vec3 Hh=normalize(Ld+V);
    c+=att*(.02*Ld.y+.22*pow(max(Hh.y,0.),60.));
  }
  gl_FragDepth=clamp(t/60.,0.,1.);
  o=vec4(vec3(c*uAmt*exp(-.2*max(t-2.6,0.))),1.);
}

FS_GAUSS:
#version 300 es
precision highp float; uniform sampler2D uTex; uniform vec2 uStep; uniform vec2 uInv; out vec4 o;
void main(){
  vec2 uv=gl_FragCoord.xy*uInv; vec3 c=texture(uTex,uv).rgb*.227;
  c+=(texture(uTex,uv+uStep*1.385).rgb+texture(uTex,uv-uStep*1.385).rgb)*.316;
  c+=(texture(uTex,uv+uStep*3.231).rgb+texture(uTex,uv-uStep*3.231).rgb)*.070;
  o=vec4(c,1.);
}

FS_COMP:
#version 300 es
precision highp float; uniform sampler2D uScene,uB1,uB3; uniform vec2 uInv; uniform float uExp,uWhite,uBloom,uDim; out vec4 o;
void main(){
  vec2 uv=gl_FragCoord.xy*uInv;
  vec3 c=texture(uScene,uv).rgb+(texture(uB1,uv).rgb*.35+texture(uB3,uv).rgb*.5)*uBloom;
  c*=uExp; c=c*c/(c+.1); c=c/(1.+c)*uWhite;   // toe keeps the unlit side of the wires near black
  vec2 q=uv-.5; c*=1.-.8*dot(q,q);
  o=vec4(c*uDim,1.);
}

FS_TRACK:
#version 300 es
precision highp float;
precision highp int;
uniform sampler2D uS; uniform int uActive;
out vec4 o;
void main(){
  vec3 sum=vec3(0.); float weight=0.;
  int count=min(uActive,192);
  for(int j=0;j<192;j++){
    if(j>=count) break;
    int id=int((float(j)+.5)*float(uActive)/float(count));
    vec4 h=texelFetch(uS,ivec2((id/10000)*128,id%10000),0);
    if(h.w<.08 || any(isnan(h)) || any(isinf(h)) || length(h.xyz)>12.) continue;
    float w=smoothstep(.08,.7,h.w)*mix(.25,1.,smoothstep(.7,4.,h.w));
    sum+=h.xyz*w; weight+=w;
  }
  o=vec4(sum/max(weight,.00001),weight);
}
